'use client';

import { cn } from '@/utilities/ui';
import RichText from '@/components/RichText';
import Image from 'next/image';

import type { AudioBitsGridBlock as AudioBitsGridProps } from 'src/payload-types';

export function AudioBitsGridBlock(props: AudioBitsGridProps) {

  const { blocks } = props;

  const handleAudioClick = (audioId: string) => {
    const audioElement = document.getElementById(audioId) as HTMLAudioElement;
    if (audioElement) {
      audioElement.play();
    }
  };

  return (
    <div className={cn('hanken container mx-auto p-4')}>

      {/* Top Block */}
      {blocks?.[0] && (
        <div className="relative w-full bg-[#FDB73E] p-6 rounded-lg mb-6 overflow-hidden">
          {/* Image covering the entire block */}
          <Image
            className="absolute inset-0 w-full h-full object-cover"
            src={blocks[0].image?.url || '/placeholder.jpg'}
            alt={blocks[0].image?.alt || 'Top Block Image'}
            layout="fill"
          />
          {/* Content overlay */}
          <div className="relative z-10 text-center text-white p-6">
            <h2 className="text-2xl font-bold mb-4">{blocks[0].title}</h2>
            <RichText
              className=""
              data={blocks[0].content}
              enableGutter={false}
            />
          </div>
          {/* Background overlay */}
          <div className="absolute inset-0 bg-black bg-opacity-50"></div>
        </div>
      )}

      {/* Four Blocks Underneath */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
        {blocks?.slice(1).map((block, index) => (
          <div
            key={index}
            className="relative bg-[#FEE8C3] shadow-md cursor-pointer group overflow-hidden h-[300px]"
          >
            {/* Image covering the entire block */}
            <Image
              className="absolute inset-0 w-full h-full object-cover"
              width={300}
              height={200}
              src={block.image?.url || '/placeholder.jpg'}
              alt={block.image?.alt || 'Block Image'}
            />

            {/* Play Icon */}
            <button
              className="absolute inset-0 flex items-center justify-center z-10 opacity-100 group-hover:opacity-0 transition-opacity duration-300"
              onClick={() => handleAudioClick(`audio-${index + 1}`)}
            >
              <svg width="1288" height="362" viewBox="0 0 1288 362" fill="none" xmlns="http://www.w3.org/2000/svg" xmlns:xlink="http://www.w3.org/1999/xlink">
<mask id="mask0_1_21118" style="mask-type:luminance" maskUnits="userSpaceOnUse" x="0" y="0" width="1288" height="362">
<path d="M0.353394 0H1288V361.624H0.353394V0Z" fill="white"/>
</mask>
<g mask="url(#mask0_1_21118)">
<rect x="0.353394" y="-48.7598" width="1288.28" height="726.069" fill="url(#pattern0_1_21118)"/>
</g>
<path d="M635 197.834C652.029 197.834 665.833 184.029 665.833 167C665.833 149.972 652.029 136.167 635 136.167C617.971 136.167 604.167 149.972 604.167 167C604.167 184.029 617.971 197.834 635 197.834Z" stroke="#1E1E1E" stroke-width="4" stroke-linecap="round" stroke-linejoin="round"/>
<path d="M628.833 154.667L647.333 167L628.833 179.334V154.667Z" stroke="#1E1E1E" stroke-width="4" stroke-linecap="round" stroke-linejoin="round"/>
<defs>
<pattern id="pattern0_1_21118" patternContentUnits="objectBoundingBox" width="1" height="1">
<use xlink:href="#image0_1_21118" transform="scale(0.00078125 0.00138889)"/>
</pattern>
<image id="image0_1_21118" width="1280" height="720" preserveAspectRatio="none" xlink:href="data:image/jpeg;base64,"/>
</defs>
</svg>

            </button>

            {/* Content hidden by default, shown on hover */}
            <div className="absolute inset-0 bg-[#FDB73E] flex flex-col items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity duration-300">
              <h3 className="text-lg font-semibold text-white mb-2">{block.title}</h3>
              <RichText
                className="text-white text-center"
                data={block.content}
                enableGutter={false}
              />
            </div>
          </div>
        ))}
      </div>

    </div>
  );
}
